static const float ZCC_SPECIALIST_7_FC1_B[32] = {
  -0.32458663f, -0.03742039f, 0.26093999f, -0.09509053f, 0.28189126f, 0.04370995f, -0.18572721f, 0.18720841f, -0.00450034f, 0.01981047f, -0.28611282f, 0.35620046f, 0.39986590f, -0.18162915f, 0.09395315f, 0.56716698f, 0.06209163f, 0.54732704f, -0.08197386f, 0.24029949f, 0.47435790f, -0.16554806f, 0.63561040f, 0.53533036f, 0.19889563f, -0.11984388f, 0.18361217f, 0.01868658f, 0.63601959f, -0.23036274f, 0.22950274f, 0.09822149f
};

static const float ZCC_SPECIALIST_7_FC2_W[32] = {
  -0.48681495f, 0.29041022f, 0.44090727f, -0.47362465f, 0.20595306f, -0.11110449f, -0.13197377f, -0.40783805f, 0.79354084f, 0.90382677f, -0.73300052f, 1.07001996f, 1.02526546f, -0.39850509f, -0.47988912f, 0.92578226f, 0.36566195f, 1.08937216f, -0.44696361f, -0.30891410f, 0.71824253f, -0.46347401f, 0.77646273f, 1.14605236f, -0.08810287f, -0.49688190f, -0.30136910f, 0.11246145f, 1.53776133f, -0.31371665f, -0.30697644f, -0.32127702f
};

static const float ZCC_SPECIALIST_7_FC2_B = -0.02221768f;

/* Math helper functions */
static float zcc_scanner_sigmoid(float x) {
  return 1.0f / (1.0f + expf(-x));
}

static float zcc_scanner_relu(float x) {
  return x > 0.0f ? x : 0.0f;
}

/* Main scanning inference entry point. Takes a 32-dim feature vector and
   returns the reliability-weighted consensus vulnerability probability. */
static float zcc_scan_c_vulnerabilities(const float *features) {
  float norm_feat[32];
  int i, j, k;
  float consensus_prob = 0.0f;
  float total_weight = 0.0f;

  /* Normalize features */
  for (i = 0; i < 32; i++) {
    norm_feat[i] = (features[i] - ZCC_SCANNER_MEAN[i]) / ZCC_SCANNER_STD[i];
  }

  /* Evaluate all 8 specialists */
  for (k = 0; k < 8; k++) {
    float hidden[32];
    float fc2_out = 0.0f;
    float spec_prob = 0.0f;

    /* Layer 1: linear projection + ReLU */
    for (i = 0; i < 32; i++) {
      float sum = 0.0f;
      for (j = 0; j < 32; j++) {
        /* Select the correct specialist matrix pointer statically */
        switch(k) {
          case 0: sum += norm_feat[j] * ZCC_SPECIALIST_0_FC1_W[i][j]; break;
          case 1: sum += norm_feat[j] * ZCC_SPECIALIST_1_FC1_W[i][j]; break;
          case 2: sum += norm_feat[j] * ZCC_SPECIALIST_2_FC1_W[i][j]; break;
          case 3: sum += norm_feat[j] * ZCC_SPECIALIST_3_FC1_W[i][j]; break;
          case 4: sum += norm_feat[j] * ZCC_SPECIALIST_4_FC1_W[i][j]; break;
          case 5: sum += norm_feat[j] * ZCC_SPECIALIST_5_FC1_W[i][j]; break;
          case 6: sum += norm_feat[j] * ZCC_SPECIALIST_6_FC1_W[i][j]; break;
          case 7: sum += norm_feat[j] * ZCC_SPECIALIST_7_FC1_W[i][j]; break;
        }
      }
      switch(k) {
        case 0: sum += ZCC_SPECIALIST_0_FC1_B[i]; break;
        case 1: sum += ZCC_SPECIALIST_1_FC1_B[i]; break;
        case 2: sum += ZCC_SPECIALIST_2_FC1_B[i]; break;
        case 3: sum += ZCC_SPECIALIST_3_FC1_B[i]; break;
        case 4: sum += ZCC_SPECIALIST_4_FC1_B[i]; break;
        case 5: sum += ZCC_SPECIALIST_5_FC1_B[i]; break;
        case 6: sum += ZCC_SPECIALIST_6_FC1_B[i]; break;
        case 7: sum += ZCC_SPECIALIST_7_FC1_B[i]; break;
      }
      hidden[i] = zcc_scanner_relu(sum);
    }

    /* Layer 2: output linear projection + Sigmoid */
    for (i = 0; i < 32; i++) {
      switch(k) {
        case 0: fc2_out += hidden[i] * ZCC_SPECIALIST_0_FC2_W[i]; break;
        case 1: fc2_out += hidden[i] * ZCC_SPECIALIST_1_FC2_W[i]; break;
        case 2: fc2_out += hidden[i] * ZCC_SPECIALIST_2_FC2_W[i]; break;
        case 3: fc2_out += hidden[i] * ZCC_SPECIALIST_3_FC2_W[i]; break;
        case 4: fc2_out += hidden[i] * ZCC_SPECIALIST_4_FC2_W[i]; break;
        case 5: fc2_out += hidden[i] * ZCC_SPECIALIST_5_FC2_W[i]; break;
        case 6: fc2_out += hidden[i] * ZCC_SPECIALIST_6_FC2_W[i]; break;
        case 7: fc2_out += hidden[i] * ZCC_SPECIALIST_7_FC2_W[i]; break;
      }
    }
    switch(k) {
      case 0: fc2_out += ZCC_SPECIALIST_0_FC2_B; break;
      case 1: fc2_out += ZCC_SPECIALIST_1_FC2_B; break;
      case 2: fc2_out += ZCC_SPECIALIST_2_FC2_B; break;
      case 3: fc2_out += ZCC_SPECIALIST_3_FC2_B; break;
      case 4: fc2_out += ZCC_SPECIALIST_4_FC2_B; break;
      case 5: fc2_out += ZCC_SPECIALIST_5_FC2_B; break;
      case 6: fc2_out += ZCC_SPECIALIST_6_FC2_B; break;
      case 7: fc2_out += ZCC_SPECIALIST_7_FC2_B; break;
    }
    spec_prob = zcc_scanner_sigmoid(fc2_out);

    /* Accumulate weighted voting */
    consensus_prob += spec_prob * ZCC_SCANNER_F1_WEIGHTS[k];
    total_weight += ZCC_SCANNER_F1_WEIGHTS[k];
  }

  return total_weight > 0.0f ? (consensus_prob / total_weight) : 0.0f;
}

